import{_ as e,c as l,o as n,a3 as a}from"./chunks/framework.MI-M1z4O.js";const h=JSON.parse('{"title":"SyncSeries 공식 기술 문서 및 개발자 가이드","description":"","frontmatter":{"layout":"home","title":"SyncSeries 공식 기술 문서 및 개발자 가이드","hero":{"name":"엠파시 기술 문서","text":"SyncSeries 설치 · 구조 · 연동 가이드","tagline":"하나의 공통 기반(SyncBoot) 위에 구성된 주력 솔루션 4종과 목적별 확장 모듈의 아키텍처, API 규격, 운영 매뉴얼을 사실 그대로 정리한 공식 문서입니다.","image":{"src":"/images/syncseries-arch-hero.svg","alt":"SyncSeries 공통 기반(SyncBoot) 및 주력 솔루션 4종·확장 모듈 7종 REST/MCP 연동 아키텍처"},"actions":[{"text":"연동 구조부터 보기","link":"/ecosystem/","theme":"brand"},{"text":"전사 기술 용어집","link":"/glossary/","theme":"alt"},{"text":"소개서 · 제안서 PDF","link":"/proposals/","theme":"alt"},{"text":"통합 데모 포털 ↗","link":"https://sync.empasy.io","theme":"alt"}]},"head":[["meta",{"name":"keywords","content":"엠파시 기술 문서, Empasy Docs, SyncSeries 매뉴얼, SyncVerse, SyncETA, SyncBoot, SyncCMS, SyncInsight, SyncLLM, SyncCrawl, SyncAPIM, SyncWatch, SyncShop, SyncOps, API 문서"}],["meta",{"property":"og:title","content":"엠파시 기술 문서 (Empasy Docs) — SyncSeries 공식 개발 및 운영 가이드"}],["meta",{"property":"og:description","content":"엠파시 SyncSeries 주력 솔루션 4종과 업무별 확장 모듈의 설치, 아키텍처, API 연동 및 운영 가이드를 제공합니다."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/"}]],"features":[{"title":"SyncVerse (주력 · 협업·승인 관리)","details":"요구사항 정리, 작업 추적, 품질 점검 결과 조회 및 담당자 단계별 승인 흐름을 통합 관리합니다.","link":"/syncverse/","linkText":"가이드 보기"},{"title":"SyncETA (주력 · 자동 테스트)","details":"코딩 없는 데스크톱 시나리오 기록과 UI 변경 대응 보정, 배포 전후 화면 비교 점검을 제공합니다.","link":"/synceta/","linkText":"가이드 보기"},{"title":"SyncBoot (주력 · 업무 시스템 기반)","details":"Spring Boot 4.0과 Java 25 기반의 표준 백오피스 구조, 조직·권한 관리, 전자결재 및 감사 로그를 제공합니다.","link":"/syncboot/","linkText":"가이드 보기"},{"title":"SyncCMS (주력 · 웹사이트 관리)","details":"멀티사이트 페이지 작성, 검수·승인 흐름, 검색·접근성 사전 점검 및 다국어 현지화를 지원합니다.","link":"/synccms/","linkText":"가이드 보기"},{"title":"공통 기반 및 연동 규격 (Ecosystem)","details":"개별 모듈이 하나의 공통 기반 위에서 표준 MCP·REST 인터페이스로 연결되는 구조를 안내합니다.","link":"/ecosystem/","linkText":"구조 보기"},{"title":"데이터 · 보안 · 업무 확장 모듈","details":"SyncInsight, SyncLLM, SyncCrawl, SyncAPIM, SyncWatch, SyncShop, SyncOps 개별 가이드를 아래 표에서 확인하세요.","link":"#module-map","linkText":"전체 목록 보기"}],"footer":"Copyright © 2026 Empasy Inc. All rights reserved."},"headers":[],"relativePath":"index.md","filePath":"ko/index.md","lastUpdated":1795241272000}'),s={name:"index.md"};function r(d,t,o,i,y,g){return n(),l("div",null,[...t[0]||(t[0]=[a('<div id="solutions"></div><h2 id="본-문서-포털의-역할" tabindex="-1">본 문서 포털의 역할 <a class="header-anchor" href="#본-문서-포털의-역할" aria-label="Permalink to “본 문서 포털의 역할”">​</a></h2><blockquote><p>본 사이트(<code>doc.empasy.com</code>)는 <strong>개발자와 시스템 운영자를 위한 공식 기술 매뉴얼 및 기술 용어 원천(SSOT)</strong>입니다. 비개발자를 위한 쉬운 제품 소개는 각 제품 홈페이지(<code>*.empasy.io</code>)와 <a href="https://empasy.io/" target="_blank" rel="noreferrer">엠파시 공식 홈페이지(empasy.io)</a>에서, 설치 없는 화면 체험은 <a href="https://sync.empasy.io/" target="_blank" rel="noreferrer">통합 데모 포털(sync.empasy.io)</a>에서 이용하실 수 있으며, 생태계 전반의 표준 기술 용어는 <a href="/glossary/">전사 기술 용어집(/glossary/)</a>에서 확인하실 수 있습니다.</p></blockquote><hr><h2 id="module-map" tabindex="-1">하나의 공통 기반과 모듈 구성 <a class="header-anchor" href="#module-map" aria-label="Permalink to “하나의 공통 기반과 모듈 구성”">​</a></h2><p>SyncSeries는 서로 무관한 11개의 개별 시스템을 별도로 만든 것이 아니라, <strong>공통 백오피스·인증·감사 기반(<code>SyncBoot</code> 및 공통 모듈) 위에서 실제 기업 프로젝트에 반복적으로 필요했던 업무 기능을 모듈 단위로 정리한 구조</strong>입니다.</p><p>필요한 영역 하나만 단독으로 도입할 수 있으며, 추후 다른 모듈을 연결할 때 권한 체계와 표준 연동 규격(REST / MCP)을 그대로 공유합니다.</p><h3 id="주력-솔루션-4종" tabindex="-1">주력 솔루션 4종 <a class="header-anchor" href="#주력-솔루션-4종" aria-label="Permalink to “주력 솔루션 4종”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">솔루션</th><th style="text-align:left;">역할 요약</th><th style="text-align:left;">문서</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SyncVerse</strong></td><td style="text-align:left;">요구사항 정리, 작업 배분, 품질 점검 조회, 담당자 단계별 승인 및 이력 관리</td><td style="text-align:left;"><a href="/syncverse/">SyncVerse 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>SyncETA</strong></td><td style="text-align:left;">데스크톱 시나리오 기록(Windows/macOS), 화면 변경 보정, 배포 전후 화면 비교 테스트</td><td style="text-align:left;"><a href="/synceta/">SyncETA 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>SyncBoot</strong></td><td style="text-align:left;">Spring Boot 4.0 · Java 25 · PostgreSQL 18.6 기반 사내 관리 시스템 표준(권한·전자결재·감사 로그)</td><td style="text-align:left;"><a href="/syncboot/">SyncBoot 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>SyncCMS</strong></td><td style="text-align:left;">멀티사이트 콘텐츠 작성·검수·승인, 검색·접근성 사전 점검, 다국어 페이지 관리</td><td style="text-align:left;"><a href="/synccms/">SyncCMS 가이드 →</a></td></tr></tbody></table><h3 id="목적별-확장-모듈-7종" tabindex="-1">목적별 확장 모듈 7종 <a class="header-anchor" href="#목적별-확장-모듈-7종" aria-label="Permalink to “목적별 확장 모듈 7종”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">영역</th><th style="text-align:left;">솔루션</th><th style="text-align:left;">역할 요약</th><th style="text-align:left;">문서</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>데이터 · AI</strong></td><td style="text-align:left;"><strong>SyncInsight</strong></td><td style="text-align:left;">읽기 전용 기반 일상 언어 데이터 조회(NL2SQL), 요약 리포트 및 데이터 출처 추적</td><td style="text-align:left;"><a href="/syncinsight/">SyncInsight 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>데이터 · AI</strong></td><td style="text-align:left;"><strong>SyncLLM</strong></td><td style="text-align:left;">멀티 AI 모델 통합 연결, 유사 질문 캐싱, 부서별 예산 관리 및 개인정보 가림 처리</td><td style="text-align:left;"><a href="/syncllm/">SyncLLM 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>데이터 · AI</strong></td><td style="text-align:left;"><strong>SyncCrawl</strong></td><td style="text-align:left;">구조 변경 대응 공개 웹 데이터 수집, 노이즈 제거 및 정형 문서·벡터 저장</td><td style="text-align:left;"><a href="/synccrawl/">SyncCrawl 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>보안 관리</strong></td><td style="text-align:left;"><strong>SyncAPIM</strong></td><td style="text-align:left;">트래픽 기반 미등록 API 식별, OpenAPI 명세 불일치 진단, 위협 탐지 및 민감정보 가림</td><td style="text-align:left;"><a href="/syncapim/">SyncAPIM 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>보안 관리</strong></td><td style="text-align:left;"><strong>SyncWatch</strong></td><td style="text-align:left;">국내외 주요 보안 취약점 공지 수집·정규화, 코드 점검 및 API 방어 규칙 관리·배포</td><td style="text-align:left;"><a href="/syncwatch/">SyncWatch 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>업무 · 서비스</strong></td><td style="text-align:left;"><strong>SyncShop</strong></td><td style="text-align:left;">8개 독립 마이크로서비스 기반 이커머스, 최소 마진 기준 확인 가격 조정 및 이전 가격 복원</td><td style="text-align:left;"><a href="/syncshop/">SyncShop 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>업무 · 서비스</strong></td><td style="text-align:left;"><strong>SyncOps</strong></td><td style="text-align:left;">SI 프로젝트 계약 단가 대비 실투입 손익, 인력 배정 간트, 4대 보증보험·하도급 기한 및 연구노트 관리</td><td style="text-align:left;"><a href="/syncops/">SyncOps 가이드 →</a></td></tr></tbody></table><hr><h2 id="개발-표준-·-프로젝트-방법론-·-자료실" tabindex="-1">개발 표준 · 프로젝트 방법론 · 자료실 <a class="header-anchor" href="#개발-표준-·-프로젝트-방법론-·-자료실" aria-label="Permalink to “개발 표준 · 프로젝트 방법론 · 자료실”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">내용 요약</th><th style="text-align:left;">링크</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>전사 기술 용어집</strong></td><td style="text-align:left;">MCP, A2A, AgentScope Java, NL2SQL, GraphRAG, HITL, eBPF, FinOps 등 표준 기술 용어 정의</td><td style="text-align:left;"><a href="/glossary/">전사 기술 용어집 →</a></td></tr><tr><td style="text-align:left;"><strong>공통 모듈 및 SDK</strong></td><td style="text-align:left;">공통 코어(<code>sync-core</code>), 도메인 공통 모듈(<code>sync-module-*</code>), 연동 SDK 가이드</td><td style="text-align:left;"><a href="/sdk/">개발자 센터 →</a> · <a href="/ecosystem/shared-modules-and-sdk">공통 모듈 →</a></td></tr><tr><td style="text-align:left;"><strong>사업 전 주기 방법론</strong></td><td style="text-align:left;">제안·분석·설계·구현·테스트·이관 6단계 수행 절차 및 점검 기준</td><td style="text-align:left;"><a href="/methodology/">방법론 개요 →</a></td></tr><tr><td style="text-align:left;"><strong>표준 산출물 양식 (125종)</strong></td><td style="text-align:left;">90-8-2 전사 표준 포맷으로 통일된 단계별 오피스 125종, 동기화 마크다운 14종, 규모별 Tailoring 프리셋</td><td style="text-align:left;"><a href="/methodology/enterprise-document-templates">표준 산출물 양식 →</a></td></tr><tr><td style="text-align:left;"><strong>애자일 및 Git 협업</strong></td><td style="text-align:left;">스크럼반(Scrumban) 운영 절차, Git 브랜치 전략, 스프린트 점검표</td><td style="text-align:left;"><a href="/agile/">애자일 가이드 →</a></td></tr><tr><td style="text-align:left;"><strong>소개서 · 제안서 (PDF)</strong></td><td style="text-align:left;">요약 브로셔, 통합 제안서 및 제품별 개별 제안서 PDF 모음</td><td style="text-align:left;"><a href="/proposals/">제안서 자료실 →</a></td></tr><tr><td style="text-align:left;"><strong>SyncETA 설치 파일</strong></td><td style="text-align:left;">Windows · macOS 데스크톱 앱 공식 다운로드 페이지</td><td style="text-align:left;"><a href="https://empasy.io/ko/download_eta.html" target="_blank" rel="noreferrer">SyncETA 다운로드 ↗</a></td></tr></tbody></table><hr><h2 id="주요-현장-적용-사례" tabindex="-1">주요 현장 적용 사례 <a class="header-anchor" href="#주요-현장-적용-사례" aria-label="Permalink to “주요 현장 적용 사례”">​</a></h2><p>엠파시 엔지니어링 팀은 교육, 유통·가전, 모빌리티·보안, 공공·에너지 분야의 기업 프로젝트에서 축적한 경험을 바탕으로 SyncSeries를 발전시켜 왔습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">산업군</th><th style="text-align:left;">적용 모듈</th><th style="text-align:left;">주요 수행 내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>교육 플랫폼 기업</strong></td><td style="text-align:left;"><strong>SyncETA</strong></td><td style="text-align:left;">동시 접속 2,000명 규모의 디지털 교육 플랫폼에 자동 테스트 체계를 적용해 정기 회귀 점검 시간을 4시간에서 45분 내외로 단축</td></tr><tr><td style="text-align:left;"><strong>유통 · 가전 기업</strong></td><td style="text-align:left;"><strong>SyncBoot</strong></td><td style="text-align:left;">기존 경영관리 및 백오피스 구조를 표준 기반과 모듈 구조로 개편하고, 미사용 테이블을 정비해 배포 주기를 월 단위에서 주 단위로 단축</td></tr><tr><td style="text-align:left;"><strong>건자재 · 교육 포털</strong></td><td style="text-align:left;"><strong>SyncCMS</strong></td><td style="text-align:left;">해외 법인별 다국어 사이트와 대용량 콘텐츠 포털을 단일 관리 플랫폼으로 통합해 신규 국가 페이지 개설과 유지보수 절차를 단순화</td></tr><tr><td style="text-align:left;"><strong>보안 · 모빌리티 기업</strong></td><td style="text-align:left;"><strong>SyncAPIM · SyncBoot</strong></td><td style="text-align:left;">대용량 API 로그 고속 검색 및 보안 모니터링 환경을 구축해 실시간 이상 접근 파악 체계 정비</td></tr></tbody></table>',18)])])}const f=e(s,[["render",r]]);export{h as __pageData,f as default};
